#!/usr/bin/env node
/**
 * Generates the CLI package-docs index and the Mintlify package copies from the
 * canonical `packages/<package>/docs` directories.
 *
 * - `--check` verifies that committed generated files are current.
 * - `--skip-mintlify` only refreshes the CLI index (used during npm pack).
 *
 * Idempotent. Only files listed in docs/packages/.generated.json are removed.
 */
import { mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import {
  DOCUMENTED_PACKAGES,
  GENERATED_MANIFEST,
  GENERATED_MARKER,
  MINTLIFY_PACKAGES_DIR,
} from './lib/docs.mjs'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const DOCS_ROOT = path.join(ROOT, 'docs')
const MINTLIFY_PACKAGES = path.join(DOCS_ROOT, MINTLIFY_PACKAGES_DIR)
const CLI_DOCS = path.join(ROOT, 'packages', 'cli', 'docs')
const CLI_PACKAGES_PAGE = path.join(CLI_DOCS, 'packages.md')

const check = process.argv.includes('--check')
const skipMintlify = process.argv.includes('--skip-mintlify')
const problems = []
const expected = new Map()

function relative(file) {
  return path.relative(ROOT, file) || path.basename(file)
}

async function readText(file) {
  return readFile(file, 'utf8')
}

async function listFiles(dir, prefix = '') {
  let entries
  try {
    entries = await readdir(dir, { withFileTypes: true })
  } catch (error) {
    if (error.code === 'ENOENT') return []
    throw error
  }
  const files = []
  for (const entry of entries) {
    if (entry.name === GENERATED_MANIFEST) continue
    const next = prefix ? path.join(prefix, entry.name) : entry.name
    if (entry.isDirectory()) files.push(...(await listFiles(path.join(dir, entry.name), next)))
    else files.push(next)
  }
  return files.sort()
}

function parseFrontmatter(source) {
  const match = source.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?/)
  if (!match) return null
  const title = /^title:\s*(.+)$/m.exec(match[1])?.[1]?.trim().replace(/^["']|["']$/g, '')
  const description = /^description:\s*(.+)$/m.exec(match[1])?.[1]?.trim().replace(/^["']|["']$/g, '')
  return { title, description, match }
}

async function validatePackage(entry) {
  const manifestPath = path.join(ROOT, entry.dir, 'package.json')
  let pkg
  try {
    pkg = JSON.parse(await readText(manifestPath))
  } catch (error) {
    problems.push(`${relative(manifestPath)}: ${error.message}`)
    return null
  }
  if (pkg.name !== entry.name) {
    problems.push(`${relative(manifestPath)}: expected name ${entry.name}, found ${pkg.name}`)
  }
  if (!Array.isArray(pkg.files) || !pkg.files.includes('docs')) {
    problems.push(`${relative(manifestPath)}: files must include "docs"`)
  }
  const docsDir = path.join(ROOT, entry.dir, 'docs')
  for (const file of entry.required) {
    // packages.md is generated below and is validated by the archive checks,
    // not as a hand-authored source file.
    if (entry.slug === 'cli' && file === 'packages.md') continue
    const source = await readText(path.join(docsDir, file)).catch(() => null)
    if (source === null) {
      problems.push(`${relative(path.join(docsDir, file))}: required documentation file is missing`)
      continue
    }
    const frontmatter = parseFrontmatter(source)
    if (!frontmatter?.title) {
      problems.push(`${relative(path.join(docsDir, file))}: missing frontmatter title`)
    }
    if (!frontmatter?.description) {
      problems.push(`${relative(path.join(docsDir, file))}: missing frontmatter description`)
    }
  }
  return pkg
}

async function buildCliIndex(packages) {
  const rows = []
  for (const entry of DOCUMENTED_PACKAGES) {
    const pkg = packages.get(entry.slug)
    if (!pkg) continue
    const docsDir = path.join(ROOT, entry.dir, 'docs')
    const index = parseFrontmatter(await readText(path.join(docsDir, 'index.md')))
    const localPath =
      entry.slug === 'cli' ? 'index.md' : `../../${entry.slug}/docs/index.md`
    rows.push({
      ...entry,
      version: pkg.version,
      title: index?.title ?? entry.name,
      localPath,
    })
  }
  const lines = [
    '---',
    'title: Installed package documentation',
    'description: Generated index of the documented StackNext packages and their local documentation paths.',
    '---',
    '',
    `<!-- ${GENERATED_MARKER}. Do not edit this file. -->`,
    '',
    '# Installed package documentation',
    '',
    'This index is generated from the packages that ship documentation. It does',
    'not mean every package is installed in a project. Check the path before',
    'reading: optional packages can be absent.',
    '',
    'Versions in this table are the versions of the package that produced this',
    'archive. Read the `version` field in the package.json next to the docs',
    'directory to confirm the installed version.',
    '',
    '| Package | Version | Visibility | Role | Documentation |',
    '| --- | --- | --- | --- | --- |',
    ...rows.map(
      (row) =>
        `| \`${row.name}\` | ${row.version} | ${row.visibility} | ${row.role} | \`${row.localPath}\` |`,
    ),
    '',
    '## How to use this index',
    '',
    'Starting from `node_modules/@stacknext/cli/docs/`, read `index.md`. For every',
    'other package, use the relative path in the table. For example:',
    '',
    '```text',
    'node_modules/@stacknext/cli/docs/index.md',
    '../../next/docs/index.md   # from node_modules/@stacknext/cli/docs/',
    '```',
    '',
    'Do not assume an internal package is at the app-root `node_modules` path.',
    'If a documented path does not resolve, the package is not available. Do not',
    'instruct an agent to read a missing package directory.',
    '',
    '## Public, optional and internal packages',
    '',
    '- **Public integration packages** are intended for direct installation when',
    '  the project uses the corresponding feature.',
    '- **Internal packages** are installed as dependencies of the CLI or another',
    '  package. Their docs are for maintainers and advanced contributors.',
    '- Optional packages (`@stacknext/playwright`, `@stacknext/drizzle` and',
    '  `@stacknext/prisma`) are only present when explicitly installed.',
    '',
    '## Related',
    '',
    '- `index.md` — local documentation entry point.',
    '- `agent-setup.md` — managed AGENTS.md, MCP and skill setup.',
    '- `commands.md` — CLI reference.',
    '',
  ]
  return lines.join('\n')
}

function rewriteGeneratedLinks(source) {
  // Canonical docs link across packages as ../../<slug>/docs/<file>. The
  // Mintlify copy lives at docs/packages/<slug>/<file>, so the same target is
  // ../<slug>/<file>. Only rewrite Markdown destinations, never code paths.
  return source.replace(
    /\]\(\.\.\/\.\.\/([a-z][a-z0-9-]*)\/docs\//g,
    '](../$1/',
  )
}

function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

function stripDuplicateTitle(source) {
  const frontmatter = parseFrontmatter(source)
  if (!frontmatter?.title) return source
  const end = frontmatter.match[0].length
  const rest = source.slice(end)
  // The H1 can follow a generated comment (the CLI package index), so match it
  // anywhere before the first H2 instead of only at the start of the body.
  const heading = new RegExp(
    `^#[\\t ]+${escapeRegExp(frontmatter.title)}[\\t ]*#*[\\t ]*(?:\\r?\\n|$)`,
    'm',
  )
  if (!heading.test(rest)) return source
  return `${source.slice(0, end)}${rest.replace(heading, '')}`
}

function stripGeneratedComment(source) {
  // The CLI index carries its own generated HTML comment. Remove it before the
  // website banner is added so the generated copy has a single marker.
  return source.replace(
    /<!-- Generated by scripts\/sync-docs\.mjs[\s\S]*? -->\s*/g,
    '',
  )
}

function withGeneratedBanner(source, sourcePath) {
  const frontmatter = parseFrontmatter(source)
  // MDX does not accept HTML comments. This form is valid MDX and still clearly
  // marks the generated website copy; canonical package docs keep their H1.
  const banner = `{/* ${GENERATED_MARKER} from ${relative(sourcePath)}. Do not edit this copy. */}`
  // Preserve provenance in the MDX-compatible copies.
  const marked = source.replace(/<!-- (\/?coderabbit-ai-generated[^>]*?) -->/g, '{/* $1 */}')
  const rewritten = stripDuplicateTitle(stripGeneratedComment(rewriteGeneratedLinks(marked)))
  if (!frontmatter) return `${banner}\n\n${rewritten}`
  const end = frontmatter.match[0].length
  return `${rewritten.slice(0, end)}${banner}\n\n${rewritten.slice(end)}`
}

async function buildMintlifyCopies() {
  const generated = []
  for (const entry of DOCUMENTED_PACKAGES) {
    const sourceDir = path.join(ROOT, entry.dir, 'docs')
    const files = await listFiles(sourceDir)
    for (const file of files) {
      const sourcePath = path.join(sourceDir, file)
      const targetRelative = path.posix.join(
        MINTLIFY_PACKAGES_DIR,
        entry.slug,
        file.split(path.sep).join('/'),
      )
      const target = path.join(DOCS_ROOT, targetRelative)
      expected.set(target, withGeneratedBanner(await readText(sourcePath), sourcePath))
      generated.push(targetRelative)
    }
  }
  return generated
}

async function previousGenerated() {
  try {
    const manifest = JSON.parse(await readText(path.join(MINTLIFY_PACKAGES, GENERATED_MANIFEST)))
    return Array.isArray(manifest.files) ? manifest.files : []
  } catch {
    return []
  }
}

async function writeIfChanged(file, content) {
  const current = await readText(file).catch(() => null)
  if (current === content) return false
  if (!check) {
    await mkdir(path.dirname(file), { recursive: true })
    await writeFile(file, content)
  }
  return true
}

async function main() {
  const packages = new Map()
  for (const entry of DOCUMENTED_PACKAGES) {
    const pkg = await validatePackage(entry)
    if (pkg) packages.set(entry.slug, pkg)
  }
  if (problems.length > 0) {
    console.error(`${problems.length} documentation source problem(s):`)
    for (const problem of problems) console.error(`  - ${problem}`)
    process.exit(1)
  }

  const changed = []
  if (await writeIfChanged(CLI_PACKAGES_PAGE, await buildCliIndex(packages))) {
    changed.push(relative(CLI_PACKAGES_PAGE))
  }

  let generated = []
  if (!skipMintlify) {
    generated = await buildMintlifyCopies()
    for (const [file, content] of expected) {
      if (await writeIfChanged(file, content)) changed.push(relative(file))
    }

    const previous = await previousGenerated()
    const stale = previous.filter((file) => !generated.includes(file))
    if (stale.length > 0) {
      if (check) {
        changed.push(...stale.map((file) => `${file} (stale)`))
      } else {
        for (const file of stale) {
          await rm(path.join(DOCS_ROOT, file), { force: true })
          changed.push(`${file} (removed)`)
        }
      }
    }
    const manifest = `${JSON.stringify({ version: 1, files: generated }, null, 2)}\n`
    if (await writeIfChanged(path.join(MINTLIFY_PACKAGES, GENERATED_MANIFEST), manifest)) {
      changed.push(relative(path.join(MINTLIFY_PACKAGES, GENERATED_MANIFEST)))
    }
  }

  if (check && changed.length > 0) {
    console.error('Documentation output is out of date. Run `pnpm docs:sync`.')
    for (const file of changed) console.error(`  - ${file}`)
    process.exit(1)
  }

  if (!check) {
    console.log(
      changed.length === 0
        ? 'Documentation is already up to date.'
        : `Updated ${changed.length} documentation file(s).`,
    )
  }
}

await main()
